"""Verdicts HT1b, HT2b, HF15, HF16 (D22), tranche HT1 (nouvelle entrée), résultat RT2. Les entrées précédentes sont conservées. Idempotent."""
import sys, pathlib
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1] / "src"))
import tp2_journal as J
def last(i): return [e for e in J.entries() if e["id"] == i][-1]
F = "artifacts/results/v3/T2_all_units.csv ; T2_tests.csv"
NOTE = " Plan T2 : 4 nouvelles découpes (répétitions 1 à 4, plis 1 à 4) × 5 rotations, p = 0, graine 42, 140 logs d'entraînement par classe ; 20 couples (découpe, rotation)."
def verdict(i, statut, preuve, note=""):
    if last(i)["statut"] == "préinscrite": J.add(i, "hypothese", last(i)["titre"], last(i)["texte"], justification="Verdict établi avec la règle de décision préinscrite (D22).", statut=statut, preuve=preuve + "  Fichiers : " + F, note=note + NOTE)
verdict("HT1b", "confirmée", "Macro-F1 des classes, Transformer moins TF-IDF (mêmes logs) : −0,0545, IC95 [−0,086 ; −0,020] (borne haute ≤ 0,02) ; Wilcoxon p = 0,9997 ; signes 2 en faveur / 18 contre (p = 0,0004) ; permutation p = 0,9998. Moyennes : Transformer 0,469 ; TF-IDF 0,523.", "Sur ces découpes le Transformer est MEILLEUR de rien : il est moins bon que TF-IDF de 0,05. Cela contredit le +0,02 de la grille T (une seule découpe, répétition 0 pli 0) : l'écart dépend beaucoup de la découpe, et la grille T était sur une découpe favorable au Transformer. Estimation exploratoire sur les 50 couples (grille T + T2) : −0,0095, IC95 [−0,030 ; 0,010].")
verdict("HT2b", "non tranchée", "AUROC d'inconnu de Mahalanobis moins MSP (Transformer) : +0,0429, IC95 [0,011 ; 0,074] (contient 0,03) ; Wilcoxon unilatéral p = 0,165 ; signes 13/7 ; permutation p = 0,22.", "Les deux séries donnent +0,0325 (grille T) et +0,0429 (T2), toutes deux compatibles avec 0,03 ; estimation exploratoire sur les 50 couples : +0,0367, IC95 [0,022 ; 0,052], p Wilcoxon 0,18. En pratique : Mahalanobis gagne entre +0,02 et +0,05 sur le MSP du Transformer, sans qu'on puisse dire s'il atteint exactement 0,03 ; la règle (sinon non tranchée, on arrête) est appliquée, la question du seuil exact est sans intérêt pratique (AUROC de 0,60 contre 0,65).")
verdict("HF15", "réfutée", "Macro-F1 des classes, fusion (moyenne des probabilités) : 0,508 ; Transformer 0,469 (fusion +0,040, IC95 [0,024 ; 0,055], p = 0,001) ; TF-IDF 0,523 (fusion −0,015, IC95 [−0,036 ; 0,009], signes 4/16) : la fusion ne dépasse pas le meilleur de ses composants (TF-IDF) ; la borne haute de l'IC95 de l'écart avec le meilleur composant (0,009) exclut +0,01.", "La fusion n'améliore que le moins bon des deux : une moyenne de probabilités avec un Transformer plus faible tire TF-IDF vers le bas.")
verdict("HF16", "non tranchée", "AUROC de la confiance de famille : fusion 0,664 ; TF-IDF 0,656 ; Transformer 0,647. Fusion moins meilleur composant (TF-IDF) : +0,008, IC95 [−0,019 ; 0,037] (contient 0,01) ; moins Transformer : +0,018, IC95 [−0,010 ; 0,046] ; p unilatéraux 0,64 et 0,26.", "Pas de gain établi : ni confirmée ni réfutée au sens de la règle ; aucun intérêt pratique visible (+0,008).")
if last("HT1")["statut"] == "non tranchée" and "T2" not in (last("HT1").get("note") or ""):
    J.add("HT1", "hypothese", last("HT1")["titre"], last("HT1")["texte"], justification="Tranchée par la réplication préinscrite D22 (HT1b, 20 couples) ; l'entrée « non tranchée » précédente est conservée.", statut="confirmée", preuve="Voir HT1b : Transformer − TF-IDF = −0,0545, IC95 [−0,086 ; −0,020].", note="Source : T2. Le Transformer n'améliore pas de plus de 0,02 ; sur 140 logs par classe il est même moins bon que TF-IDF sur les nouvelles découpes.")
if not J.exists("RT2"):
    J.add("RT2", "resultat", "Réplication Transformer T2 et fusion I3 (grille T conservée)",
          "20 couples : macro-F1 des classes : TF-IDF 0,523 ; fusion 0,508 ; Transformer 0,469. AUROC d'inconnu : famille fusion 0,664 ; famille TF-IDF 0,656 ; famille Transformer 0,647 ; Mahalanobis Transformer 0,647 ; MSP TF-IDF 0,629 ; MSP fusion 0,627 ; MSP Transformer 0,604. Grille T (une découpe) : Transformer 0,42 à 0,37 contre TF-IDF 0,39 à 0,36.",
          justification="Conclusion sur le Transformer : avec 140 logs par classe, il ne bat pas TF-IDF (l'avantage de la grille T venait d'une découpe favorable) et la fusion n'améliore pas la classification ni le rejet : pas de gain à attendre ; I3 est close sans gain. Le pipeline reste TF-IDF (mots + lettres pour la famille) avec rejet par confiance de famille.", preuve=F)
print("ok")
